async function postToSlack(text, channelId, accessToken) {
  // **Helpfulness (High Priority):** Clearly structured, explains functionality & parameters
  /**
   * Posts a message to a specified Slack channel using the provided API token.
   *
   * @param {string} text - The message content to send.
   * @param {string} channelId - The unique ID of the Slack channel.
   * @param {string} accessToken -  A valid Slack API access token with necessary permissions.
   * @returns {Promise<object>} Resolves with the Slack API's response object on success, 
                         rejects with an error on failure.
   */
  try {
    const slackWebhookUrl = `https://slack.com/api/chat.postMessage`; // Base API endpoint
    const payload = {
      channel: channelId,
      text: text,
      // Add optional parameters like thread_ts, username, etc. for richer formatting here
    };

    const response = await fetch(slackWebhookUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${accessToken}`, // Authenticate with the token
      },
      body: JSON.stringify(payload),
    });

    if (!response.ok) {
      throw new Error(`Slack API Error: ${await response.text()} `); 
    }
