```cpp
#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function
int fibonacci(int a, int b, int n) {
    if (n == 0) return a;  // Base case: Return the first element if n is 0
    else if (n == 1) return b; // Base case: Return the second element if n is 1
    else return fibonacci(b, a + b, n - 1); // Recursive step
}

int main() {
    int start1, start2, count;

    cout << "Enter the first two integers of the sequence: ";
    while (!(cin >> start1 >> start2)) {  // Error handling for non-numeric input
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        cerr << "Invalid input. Please enter integers only.\n";
    }

    cout << "Enter the desired number of sequence elements: ";
    while (!(cin >> count) || count <= 0) {  // Error handling for non-positive count
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        cerr << "Invalid input. Enter a positive integer.\n";
    }

    cout << "Fibonacci Sequence (starting with " << start1 << ", " << start2 << "): ";
    for (int i = 0; i < count; ++i) {
        cout << fibonacci(start1, start2, i) << " ";
        start1 = start2;  // Update for next iteration
        start2 = fibonacci(start1, start2, i); //  Calculate and update the 'next' element
    }
    cout << endl;

    return 0;
}
```

