using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json; // Assuming JSON serialization/deserialization

public class RestServiceWrapper<T> where T : class
{
    private readonly HttpClient _client;
    private readonly string _baseUrl;
    private string _authToken;

    public RestServiceWrapper(string baseUrl, string initialAuthToken = null)
    {
        _baseUrl = baseUrl;
        _authToken = initialAuthToken;
        _client = new HttpClient { BaseAddress = new Uri(_baseUrl) };
        // Add custom headers or settings to the HttpClient here if needed
    }

    public void SetAuthToken(string token) => _authToken = token;

    /// <summary>
    /// Generic GET request handler with auth token injection.
    /// </summary>
    public async Task<T> GetAsync(string apiEndpoint, params (string key, object value)[] queryParams)
    {
        var uriBuilder = new UriBuilder(_baseUrl + apiEndpoint);
        if (queryParams.Length > 0)
        {
            var query = HttpUtility.ParseQueryString(uriBuilder.Query);
            foreach ((string key, object value) in queryParams)
                query[key] = value.ToString();
            uriBuilder.Query = query.ToString();
        }

        return await AddAuthAndExecute<T>(HttpMethod.Get, uriBuilder.Uri);
    }

    /// <summary>
    /// Generic POST request handler with auth token and payload handling.
    /// </summary>
    public async Task<T> PostAsync<TPayload>(string apiEndpoint, TPayload payload)
    where TPayload : class
    {
        var content = JsonConvert.SerializeObject(payload);
        return await AddAuthAndExecute<T>(HttpMethod.Post, apiEndpoint, content);
    }

    private async Task<T> AddAuthAndExecute<T>(HttpMethod method, string uri, string content = null)
    {
        using var request = new HttpRequestMessage(method, uri)
        {
            Content = content != null ? new StringContent(content, System.Text.Encoding.UTF8, "application/json") : null
        };
        // Inject auth token into header
        request.Headers.Add("Authorization", $"Bearer {_authToken}");

