function determineMostRelevantProtocol(inputData) {
  // Analyze input data for protocol relevance:

  // High weight on IPv6 indication (source/destination IPs format)
  if (inputData.sourceIP.startsWith("2001:") && inputData.destinationIP.startsWith("2001:")) {
    //  Strong IPv6 usage signals IPv6 protocol relevance (high helpfulness)
    return "IPv6"; 
  }

  //  HTTP determined by port (80) and textual payload (suggestive, though not definitive)
  if (inputData.port === 80 && typeof inputData.payload === 'string') {
    return "HTTP"; //  Reasonable HTTP likelihood (moderate helpfulness)
  }

  // UDP applicability less direct from this data alone, consider for scenarios with absent port specificity or unreliable payload analysis (lower helpfulness)
  //  Return UDP only if no stronger indicator exists, otherwise, ambiguity prevails.
  return "UDP"; //  Least directly supported but a possibility (lower helpfulness)
}

