import { Injectable } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { Reflector } from '@nestjs/core';
import { PrismaService } from './prisma.service';
import { Role } from '../entities/user.entity';

@Injectable()
export class RolesAuthGuard extends AuthGuard('jwt') {
  constructor(private reflector: Reflector, private prisma: PrismaService) { super(); }

  canActivate(context: ExecutionContext): boolean | Promise<boolean> {
    const requiredRoles = this.reflector.get<Role[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // Public endpoint

    const user = context.switchToHttp().getRequest().user;
    return this.prisma.user.findUnique({ where: { id: user.id } }).then(usr => 
      requiredRoles.some(role => usr?.roles.includes(role))
    );
  }
}

// Example permissions array (in AppModule or config)
export const PERMISSIONS = [
  'READ_DATA', 'CREATE_POSTS', 'MANAGE_USERS', 'ADMIN_ONLY', // ...more
];
```

