function geocodeAndPopulate(spreadsheet, sheetName, placeColumn, latColumn, lngColumn) {
  // 1. Get Spreadsheet and Data Range
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);
  const dataRange = sheet.getRange(placeColumn); // Assuming your place names start from row 1 in the specified column

  // 2. Initialize Places Service & Logger (for debugging)
  const placesService = new google.maps.places.PlacesService(SpreadsheetApp.getActive());
  Logger.log("Geocoding initiated...");

  // 3. Loop through Place Names and Geocode
  dataRange.getValues().forEach((row, rowIndex) => {
    const placeName = row[0]; // Extract place name from each row
    if (placeName) {  
      const request = {
        query: placeName,
        fields: ['geometry', 'formatted_address'] // Request only latitude/longitude and address (optional)
      };
      placesService.findPlaceFromQuery(request, (results, status) => {
        if (status === google.maps.places.PlacesServiceStatus.OK && results && results.length > 0) {
          const place = results[0];
          const lat = place.geometry.location.lat();
          const lng = place.geometry.location.lng();

          // 4. Update Spreadsheet with Lat/Lng
          sheet.getRange(rowIndex + 1, latColumn).setValue(lat);  // +1 for zero-based indexing
          sheet.getRange(rowIndex + 1, lngColumn).setValue(lng);
          Logger.log(`Geocoded "${placeName}" - Lat: ${lat}, Lng: ${lng}`); 
        } else {
          Logger.log(`WARNING: Geocoding for "${placeName}" failed with status: ${status}`);
          // Handle geocoding errors (e.g., logging, placeholder values, etc.)
        }
      });
    }
  });
  Logger.log("Geocoding complete.");
}
